# Readable Russian spacing around numbers in free prose is manually improved for common joins.
text='\n'.join(s)+'\n'
import re
text=re.sub(r'(?<=[А-Яа-яA-Za-z])(?=\d)', ' ',text)
text=re.sub(r'(?<=\d)(?=[А-Яа-я])', ' ',text)
# Do not alter artifact paths or scientific keys: regex only affects prose; paths digits followed underscore remain intact.
text=text.replace('M 1','M1')
text=re.sub(r'(?<=[A-Za-z])(?=[А-Яа-я])', ' ',text)
text=re.sub(r'(?<=%)(?=[А-Яа-яA-Za-z])', ' ',text)
text=re.sub(r'(?<=\d)(?=bps)', ' ',text)
text=re.sub(r':(?=\d)', ': ',text)
text=re.sub(r',(?=\d)', ', ',text)
text=re.sub(r'—(?=\S)', '— ',text)
text=re.sub(r'(?<=\S)—', ' —',text)
text=text.replace('более$', 'более $').replace('У 19 контрольных', 'У 19 контрольных')
(OUT/'REPORT_RU.md').write_text(text)
